import{_ as a,c as t,o as r,a5 as i}from"./chunks/framework.DYgWcJ6Z.js";const p=JSON.parse('{"title":"References","description":"","frontmatter":{},"headers":[],"relativePath":"manual/references.md","filePath":"manual/references.md","lastUpdated":1754235051000}'),n={name:"manual/references.md"};function s(o,e,l,c,h,d){return r(),t("div",null,e[0]||(e[0]=[i('<h1 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h1><p>In this chapter, we will provide a list of references, the technical documentations and specifications to help developers learn more about advanced features.</p><h2 id="runtime-apis" tabindex="-1">Runtime APIs <a class="header-anchor" href="#runtime-apis" aria-label="Permalink to &quot;Runtime APIs&quot;">​</a></h2><p>JSAR is a Web runtime, and it provides a set of APIs that follow the Web platform standards, such as DOM, WebGL, WebXR, and WebAssembly. And it also provides two additional APIs, the one is part of the Node.js APIs for testing and debugging purposes, and the other is the JSAR-specific APIs for the runtime itself.</p><ul><li><a href="./references/web-apis.html">Web APIs</a></li><li><a href="./references/jsar-apis.html">JSAR APIs</a></li></ul><h2 id="graphics" tabindex="-1">Graphics <a class="header-anchor" href="#graphics" aria-label="Permalink to &quot;Graphics&quot;">​</a></h2><p>These documentations will help you to learn more about how the WebGL works in JSAR, and which graphics backends have been supported by JSAR&#39;s unified mixed-rendering architecture. And also here, you can find the references about the WebGL extensions that JSAR supports.</p><ul><li><a href="./references/webgl-and-extensions.html">WebGL and extensions</a></li><li><a href="./references/graphics-backends.html">Graphics backends</a></li></ul><h2 id="webxr-and-input-sources" tabindex="-1">WebXR and input sources <a class="header-anchor" href="#webxr-and-input-sources" aria-label="Permalink to &quot;WebXR and input sources&quot;">​</a></h2><p>JSAR implements the <a href="https://developer.mozilla.org/en-US/docs/Web/API/WebXR_Device_API" target="_blank" rel="noreferrer">WebXR Device API</a> to run WebXR applications, here you can find the references about the WebXR Device API and the input sources that JSAR supports.</p><ul><li><a href="./references/webxr-basis.html">WebXR basis</a></li><li><a href="./references/webxr-input-sources.html">WebXR input sources</a></li></ul><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>There is a set of device configuration that you can use to debug and test your applications.</p><ul><li><a href="./references/runtime-configuration.html">Runtime configuration</a></li></ul><h2 id="embedders" tabindex="-1">Embedders <a class="header-anchor" href="#embedders" aria-label="Permalink to &quot;Embedders&quot;">​</a></h2><p>If you are a developer who wants to embed JSAR into your application or platform, you can find the embedder APIs and guides here, currently JSAR provides the native C++ APIs and Unity C# APIs to work with.</p><ul><li><a href="./references/native-apis.html">Native APIs</a></li><li><a href="./references/unity-apis.html">Unity APIs</a></li></ul><h2 id="language-specifications" tabindex="-1">Language specifications <a class="header-anchor" href="#language-specifications" aria-label="Permalink to &quot;Language specifications&quot;">​</a></h2><p>JSAR created new languages: XSML and SpatialCSS, and also extends the HTML and CSS to support the spatialized elements and attributes. Here you can find the complete specifications of these new and extended languages.</p><ul><li><a href="./references/xsml.html">XSML</a></li><li><a href="./references/spatial-css.html">SpatialCSS</a></li></ul>',20)]))}const f=a(n,[["render",s]]);export{p as __pageData,f as default};
